// Glosario (español). Cada término: id, term (como se muestra), aliases (otras formas que se
// marcan en los textos), def (para principiantes), example (en esta sala), ref (norma o fuente).
// Los términos se marcan solos en alertas, observaciones, runbooks y explicaciones.
export default [
  { id: 'rack', term: 'rack', aliases: ['racks'], def: 'Gabinete metálico normalizado de 19 pulgadas donde se montan servidores, switches y otros equipos, uno sobre otro.', example: 'La Sala A tiene 10 racks, de R01 a R10, en dos filas.', ref: 'ANSI/TIA-942' },
  { id: 'u', term: 'U', aliases: ['unidad de rack'], def: 'Unidad de altura de un rack: 1 U mide 44,45 mm. Un equipo «2U» ocupa dos unidades.', example: 'k8s-n7 ocupa U23–U24 en R06; el rack tiene 42 U numeradas.', ref: 'EIA-310' },
  { id: 'panel-ciego', term: 'panel ciego', aliases: ['paneles ciegos'], def: 'Tapa que cierra las U vacías del frente de un rack para que el aire caliente de atrás no vuelva al frente.', example: 'En R08 faltan paneles ciegos entre U30 y U34, y la entrada superior se calienta.', ref: 'ASHRAE TC 9.9 · EU Code of Conduct' },
  { id: 'pasillo-frio', term: 'pasillo frío', aliases: ['pasillos fríos'], def: 'Pasillo al que miran los frentes de los racks: por ahí llega el aire frío que toman los equipos.', example: 'Las filas A y B se miran por el pasillo frío, que tiene baldosas perforadas.', ref: 'ASHRAE TC 9.9' },
  { id: 'pasillo-caliente', term: 'pasillo caliente', aliases: ['pasillos calientes'], def: 'Pasillo al que miran las partes traseras de los racks: por ahí sale el aire caliente de los equipos.', example: 'Detrás de cada fila queda un pasillo caliente que vuelve hacia los CRAC.', ref: 'ASHRAE TC 9.9' },
  { id: 'contencion', term: 'contención', aliases: ['contencion'], def: 'Puertas y techo que encierran un pasillo para que el aire frío y el caliente no se mezclen.', example: 'El pasillo frío de la Sala A tiene puertas de vidrio; abrirlas rompe la contención.', ref: 'ASHRAE TC 9.9' },
  { id: 'crac', term: 'CRAC', aliases: [], def: 'Unidad de climatización de precisión de la sala (Computer Room Air Conditioner): enfría el aire y lo impulsa bajo el piso.', example: 'CRAC-1 enfría la fila A y CRAC-2 la fila B.', ref: 'ASHRAE TC 9.9' },
  { id: 'setpoint', term: 'setpoint', aliases: [], def: 'Temperatura objetivo configurada en un equipo de climatización.', example: 'Bajar el setpoint a 16 °C gasta más energía y no corrige un panel ciego faltante.', ref: 'ASHRAE TC 9.9' },
  { id: 'impulsion', term: 'impulsión', aliases: ['impulsion'], def: 'Aire frío que entrega la unidad de climatización.', example: 'Con el compresor detenido, la impulsión de CRAC-2 sube de 18 °C.', ref: 'ASHRAE TC 9.9' },
  { id: 'retorno', term: 'retorno', aliases: [], def: 'Aire caliente que vuelve a la unidad de climatización después de pasar por los equipos.', example: 'CRAC-1 recibe un retorno de unos 30 °C.', ref: 'ASHRAE TC 9.9' },
  { id: 'pdu', term: 'PDU', aliases: ['PDUs'], def: 'Regleta de distribución de energía del rack (Power Distribution Unit). Suele haber dos, una por rama.', example: 'Cada rack tiene PDU-A y PDU-B verticales en la parte trasera.', ref: 'ANSI/TIA-942' },
  { id: 'rama', term: 'rama A/B', aliases: ['rama A', 'rama B', 'ramas A y B'], def: 'Cada uno de los dos caminos de energía independientes que llegan al rack, desde UPS distintas.', example: 'La rama A viene de UPS-A y la rama B de UPS-B.', ref: 'Uptime Institute Tiers · TIA-942' },
  { id: 'redundancia', term: 'redundancia', aliases: ['redundante'], def: 'Tener un respaldo para que la falla de un componente no detenga el servicio.', example: 'Un servidor con una fuente en cada rama (A + B) sigue encendido si una rama falla.', ref: 'Uptime Institute Tiers' },
  { id: 'psu', term: 'PSU', aliases: ['fuente', 'fuentes', 'PSU1', 'PSU2'], def: 'Fuente de poder de un equipo (Power Supply Unit). Los servidores suelen tener dos.', example: 'k8s-n7 tiene la PSU1 y la PSU2 conectadas a PDU-B.', ref: 'ANSI/TIA-942' },
  { id: 'ups', term: 'UPS', aliases: [], def: 'Sistema de alimentación ininterrumpida: entrega energía desde baterías si falla la red.', example: 'UPS-A alimenta todas las PDU-A; UPS-B, todas las PDU-B.', ref: 'IEEE 1188' },
  { id: 'bypass', term: 'bypass', aliases: [], def: 'Modo en que la UPS deja pasar la red directo a la carga, sin protección de baterías.', example: 'Pasar UPS-A a bypass durante la prueba deja la carga sin protección.', ref: 'IEEE 1188' },
  { id: 'autonomia', term: 'autonomía', aliases: ['autonomia'], def: 'Tiempo que la UPS puede sostener la carga solo con baterías.', example: 'UPS-A informa unos 22 minutos de autonomía.', ref: 'IEEE 1188' },
  { id: 'generador', term: 'generador', aliases: [], def: 'Motor que genera energía cuando la red falla por mucho tiempo; la UPS cubre mientras arranca.', example: 'No se arranca a mano por una autoprueba de batería programada.', ref: 'Uptime Institute Tiers' },
  { id: 'ipmi', term: 'IPMI', aliases: [], def: 'Interfaz de gestión fuera de banda de un servidor: permite ver temperaturas internas y encenderlo o apagarlo a distancia.', example: 'Por IPMI, los servidores de R04 reportan 22–24 °C aunque el sensor marque 34 °C.', ref: 'Especificación IPMI' },
  { id: 'piso-tecnico', term: 'piso técnico', aliases: ['piso tecnico'], def: 'Piso elevado de baldosas removibles; debajo pasan el aire frío y los cables.', example: 'La fuga de condensado está bajo el piso técnico, en la zona 3.', ref: 'ANSI/TIA-942' },
  { id: 'vesda', term: 'VESDA', aliases: [], def: 'Sistema de detección temprana de humo por aspiración: toma muestras de aire continuamente.', example: 'Se revisa en la ronda de inicio de turno junto con los extintores.', ref: 'NFPA 76' },
  { id: 'colocation', term: 'colocation', aliases: [], def: 'Datacenter que arrienda espacio, energía y climatización a varios clientes para sus propios equipos.', example: 'Cordillera Colo aloja equipos de Retail Andino, Fintech Pehuén y Logística Austral.', ref: 'Uptime Institute' },
  { id: 'remote-hands', term: 'remote hands', aliases: ['manos remotas'], def: 'Servicio en que el personal del datacenter hace tareas físicas simples a pedido del cliente.', example: 'Mover una fuente de k8s-n7 con autorización de Fintech Pehuén es un trabajo de remote hands.', ref: 'ITIL 4 · gestión de solicitudes' },
  { id: 'cambio', term: 'cambio (CHG)', aliases: ['cambio aprobado', 'CHG'], def: 'Trabajo planificado y aprobado sobre la infraestructura, con fecha, responsable y alcance.', example: 'CHG-1042 autoriza el reemplazo del disco de stg-02 de 08:00 a 10:00.', ref: 'ITIL 4 · ISO/IEC 20000-1' },
  { id: 'sla', term: 'SLA', aliases: [], def: 'Acuerdo de nivel de servicio: los tiempos comprometidos para tomar y resolver un ticket según su prioridad.', example: 'Un P1 se toma en 5 minutos y se resuelve en 25.', ref: 'ITIL 4 · ISO/IEC 20000-1' },
  { id: 'mtta', term: 'MTTA', aliases: [], def: 'Tiempo medio en tomar (acusar recibo de) un ticket desde que se abre.', example: 'El informe de fin de turno calcula tu MTTA.', ref: 'ITIL 4' },
  { id: 'mttr', term: 'MTTR', aliases: [], def: 'Tiempo medio en resolver un ticket desde que se abre.', example: 'Resolver rápido sin saltarse pasos baja el MTTR.', ref: 'ITIL 4' },
  { id: 'prioridad', term: 'P1–P4', aliases: ['P1', 'P2', 'P3', 'P4'], def: 'Prioridad del ticket según impacto y urgencia: P1 crítica, P2 alta, P3 media, P4 baja.', example: 'La falla de CRAC-2 es P1; la autoprueba de la UPS, P4.', ref: 'ITIL 4' },
  { id: 'vp', term: 'verdadero positivo', aliases: [], def: 'Alerta que refleja un problema real que hay que atender.', example: 'La fuga bajo el piso técnico es un verdadero positivo.', ref: 'ITIL 4 · gestión de eventos' },
  { id: 'fp', term: 'falso positivo', aliases: [], def: 'Alerta que no refleja lo que ocurre en la sala, por ejemplo por un sensor mal ubicado.', example: 'El sensor suelto de R04 genera un falso positivo.', ref: 'ITIL 4 · gestión de eventos' },
  { id: 'benigno', term: 'benigno', aliases: [], def: 'Evento real, pero esperado o autorizado: no requiere acción correctiva.', example: 'UPS-A en batería durante su autoprueba programada es benigno.', ref: 'ITIL 4 · gestión de eventos' },
  { id: 'escalamiento', term: 'escalamiento', aliases: ['escalar', 'escala'], def: 'Pasar un ticket a quien tiene la capacidad o la autoridad para resolverlo.', example: 'Una falla de compresor se escala a Climatización y al jefe de turno.', ref: 'ITIL 4' },
  { id: 'bitacora', term: 'bitácora', aliases: ['bitacora'], def: 'Registro cronológico de lo que pasa en el turno: hallazgos, acciones y decisiones.', example: 'Las notas que mencionan el ticket (por ejemplo, «TK-103») cuentan como registro.', ref: 'ISO/IEC 20000-1' },
  { id: 'relevo', term: 'relevo', aliases: ['relevo de turno'], def: 'Entrega de información al turno siguiente: qué quedó abierto, qué vigilar y a quién se escaló.', example: 'Al final del turno escribes el relevo en el informe.', ref: 'ITIL 4' },
  { id: 'recirculacion', term: 'recirculación', aliases: ['recirculacion'], def: 'Aire caliente que vuelve a la entrada de los equipos en vez de regresar a la climatización.', example: 'Por el hueco de R08 el aire caliente recircula hacia el frente.', ref: 'ASHRAE TC 9.9' },
  { id: 'ashrae', term: 'ASHRAE', aliases: [], def: 'Asociación que publica las recomendaciones de temperatura y humedad para salas de equipos.', example: 'El rango recomendado de entrada es de 18 a 27 °C.', ref: 'ASHRAE TC 9.9' },
];
